--[[
多动作打飞脚本 · 全中文一键快捷键
原脚本逻辑零改动：整份原码原样内嵌，照常由加载函数执行；
外层只多一个手机可点的悬浮按钮，短按 = 执行一次「当前选中的动作」。

用法：整份粘贴进执行器运行即可。
想改用远程加载：把下面「原始地址」填上原脚本直链，内嵌码会被忽略。
短按 = 执行    拖动 = 挪位置    长按 = 设置（认不出原脚本按钮时手动指定）
]]

local CFG = {
    ["原始地址"] = "",
    ["兜底按键"] = Enum.KeyCode.F,   -- 找不到原脚本按钮时改发这个键
    ["扫描等待"] = 3.0,              -- 等原脚本把界面建出来的最长秒数
    ["匹配词"]   = {"打飞","执行","触发","开始","启动","发射","使用","确定","开火","动作","攻击","释放","放出","一键","确认","击飞","打出去","运行","生效"},
}

local Players = game:GetService("Players")
local UIS     = game:GetService("UserInputService")
local VIM     = game:GetService("VirtualInputManager")
local LP      = Players.LocalPlayer
local Gui     = LP:WaitForChild("PlayerGui")
local Cam     = workspace.CurrentCamera

local roots = { Gui }
pcall(function() roots[#roots + 1] = game:GetService("CoreGui") end)

