-- ---------- 1. 原样执行原脚本 ----------
local before = {}
for _, r in ipairs(roots) do
    for _, d in ipairs(r:GetDescendants()) do before[d] = true end
end

local ok, err = pcall(function()
    if CFG["原始地址"] ~= "" then
        loadstring(game:HttpGet(CFG["原始地址"]))()
    else
        loadstring(ORIGINAL_CODE)()
    end
end)
if not ok then warn("[快捷键] 原脚本运行出错：" .. tostring(err)) end

-- ---------- 2. 悬浮按钮 ----------
local HotkeyGui = Instance.new("ScreenGui")
HotkeyGui.Name           = "打飞快捷键"
HotkeyGui.ResetOnSpawn   = false
HotkeyGui.IgnoreGuiInset = true
HotkeyGui.DisplayOrder   = 999
HotkeyGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
pcall(function() HotkeyGui.Parent = game:GetService("CoreGui") end)
if not HotkeyGui.Parent then HotkeyGui.Parent = Gui end

local vp = Cam.ViewportSize
local function clampPos(x, y)
    return math.clamp(x, 0, vp.X - 68), math.clamp(y, 0, vp.Y - 68)
end

local btn = Instance.new("TextButton", HotkeyGui)
btn.Name = "执行按钮"
btn.Size = UDim2.fromOffset(62, 62)
btn.Position = UDim2.fromOffset(clampPos(vp.X * 0.80, vp.Y * 0.42))
btn.BackgroundColor3 = Color3.fromRGB(22, 24, 30)
btn.BackgroundTransparency = 0.15
btn.TextColor3 = Color3.new(1, 1, 1)
btn.Text = "执行"
btn.TextSize = 15
btn.Font = Enum.Font.GothamBold
btn.Active = true
Instance.new("UICorner", btn).CornerRadius = UDim.new(0.5, 0)
local stroke = Instance.new("UIStroke", btn)
stroke.Color = Color3.fromRGB(120, 170, 255)
stroke.Thickness = 2
stroke.Transparency = 0.25

local toast = Instance.new("TextLabel", HotkeyGui)
toast.Name = "提示条"
toast.AnchorPoint = Vector2.new(0.5, 1)
toast.Position = UDim2.new(0.5, 0, 0.90, 0)
toast.Size = UDim2.fromOffset(280, 34)
toast.BackgroundColor3 = Color3.fromRGB(15, 17, 22)
toast.BackgroundTransparency = 0.2
toast.TextColor3 = Color3.new(1, 1, 1)
toast.TextSize = 13
toast.Font = Enum.Font.Gotham
toast.Text = ""
toast.Visible = false
Instance.new("UICorner", toast).CornerRadius = UDim.new(0, 10)
local toastTick = 0
local function say(msg)
    toast.Text = msg
    toast.Visible = true
    toastTick = toastTick + 1
    local mine = toastTick
    task.delay(2.2, function()
        if toastTick == mine then toast.Visible = false end
    end)
end

-- ---------- 3. 运行时发现原脚本的执行按钮 ----------
local candidates, target = {}, nil
local useKeyOnly, signalMode, panelOpen = false, false, false
local manualBind = false
local NEGATIVE = {"关闭","取消","设置","收起","隐藏","退出","删除"}

local function scan()
    candidates = {}
    for _, r in ipairs(roots) do
        for _, d in ipairs(r:GetDescendants()) do
            if not before[d]
                and not d:IsDescendantOf(HotkeyGui)
                and (d:IsA("TextButton") or d:IsA("ImageButton")) then
                candidates[#candidates + 1] = d
            end
        end
    end
end

local function btnText(b)
    return b:IsA("TextButton") and tostring(b.Text or "") or ""
end

local function score(b)
    local s = string.lower(btnText(b) .. " " .. tostring(b.Name or ""))
    local n = 0
    for _, w in ipairs(CFG["匹配词"]) do
        if string.find(s, string.lower(w), 1, true) then n = n + 1 end
    end
    for _, w in ipairs(NEGATIVE) do
        if string.find(s, string.lower(w), 1, true) then n = n - 2 end
    end
    return n
end

local function autoPick()
    local best, bs = nil, 0
    for _, b in ipairs(candidates) do
        local s = score(b)
        if s > bs then best, bs = b, s end
    end
    if not best then
        for _, b in ipairs(candidates) do
            if score(b) >= 0 then best = b; break end
        end
    end
    target = best
    manualBind = false
end

-- ---------- 4. 触发 ----------
local function clickBtn(b)
    local p, z = b.AbsolutePosition, b.AbsoluteSize
    local x, y = p.X + z.X / 2, p.Y + z.Y / 2
    pcall(function()
        VIM:SendMouseButtonEvent(x, y, 0, true, game, 0)
        task.wait(0.05)
        VIM:SendMouseButtonEvent(x, y, 0, false, game, 0)
    end)
end

local function fireBtn(b)
    if signalMode and typeof(firesignal) == "function" then
        if pcall(firesignal, b.MouseButton1Click) then return end
    end
    clickBtn(b)
end

local function sendKey()
    pcall(function()
        VIM:SendKeyEvent(true, CFG["兜底按键"], false, game)
        task.wait(0.05)
        VIM:SendKeyEvent(false, CFG["兜底按键"], false, game)
    end)
end

local function alive(b)
    return b and b.Parent and b.Visible and b.AbsoluteSize.X > 2
end

local function fire()
    if useKeyOnly then sendKey(); return end
    if not alive(target) then
        if manualBind then say("原按钮已隐藏 · 长按重新指定"); return end
        scan(); autoPick()
    end
    if alive(target) then fireBtn(target); return end
    sendKey()
end

-- ---------- 5. 设置面板（长按打开） ----------
local panel = Instance.new("Frame", HotkeyGui)
panel.Name = "设置面板"
panel.AnchorPoint = Vector2.new(0.5, 0.5)
panel.Position = UDim2.new(0.5, 0, 0.5, 0)
panel.Size = UDim2.fromOffset(300, 360)
panel.BackgroundColor3 = Color3.fromRGB(18, 20, 26)
panel.BackgroundTransparency = 0.05
panel.Visible = false
Instance.new("UICorner", panel).CornerRadius = UDim.new(0, 14)

local pTitle = Instance.new("TextLabel", panel)
pTitle.Size = UDim2.new(1, 0, 0, 38)
pTitle.BackgroundTransparency = 1
pTitle.TextColor3 = Color3.new(1, 1, 1)
pTitle.TextSize = 15
pTitle.Font = Enum.Font.GothamBold
pTitle.Text = "设置触发目标"

local list = Instance.new("ScrollingFrame", panel)
list.Position = UDim2.fromOffset(10, 42)
list.Size = UDim2.fromOffset(280, 236)
list.BackgroundTransparency = 1
list.ScrollBarThickness = 3
list.AutomaticCanvasSize = Enum.AutomaticSize.Y
local lay = Instance.new("UIListLayout", list)
lay.Padding = UDim.new(0, 4)
lay.SortOrder = Enum.SortOrder.LayoutOrder

local function mkBtn(parent, text, y, w, h)
    local b = Instance.new("TextButton", parent)
    b.Position = UDim2.fromOffset(10, y)
    b.Size = UDim2.fromOffset(w, h)
    b.BackgroundColor3 = Color3.fromRGB(38, 42, 54)
    b.TextColor3 = Color3.new(1, 1, 1)
    b.TextSize = 12
    b.Font = Enum.Font.Gotham
    b.Text = text
    Instance.new("UICorner", b).CornerRadius = UDim.new(0, 8)
    return b
end

local keyBtn    = mkBtn(panel, "", 286, 176, 30)
local modeBtn   = mkBtn(panel, "", 286, 94, 30)
modeBtn.Position = UDim2.fromOffset(196, 286)
local rescanBtn = mkBtn(panel, "重新扫描", 322, 136, 30)
local closeBtn  = mkBtn(panel, "关闭", 322, 136, 30)
closeBtn.Position = UDim2.fromOffset(154, 322)

local KEYS = {Enum.KeyCode.F, Enum.KeyCode.Q, Enum.KeyCode.E, Enum.KeyCode.R,
              Enum.KeyCode.Space, Enum.KeyCode.One, Enum.KeyCode.Two, Enum.KeyCode.Three}
local KEY_NAMES = {
    [Enum.KeyCode.F]     = "F 键",
    [Enum.KeyCode.Q]     = "Q 键",
    [Enum.KeyCode.E]     = "E 键",
    [Enum.KeyCode.R]     = "R 键",
    [Enum.KeyCode.Space] = "空格键",
    [Enum.KeyCode.One]   = "1 键",
    [Enum.KeyCode.Two]   = "2 键",
    [Enum.KeyCode.Three] = "3 键",
}
local function keyName(k) return KEY_NAMES[k] or "默认键" end
local function refreshBtns()
    keyBtn.Text  = (useKeyOnly and "【按键】" or "按键：") .. keyName(CFG["兜底按键"])
    modeBtn.Text = signalMode and "信号触发" or "真实点击"
end

local function bind(b, label)
    target, useKeyOnly, manualBind = b, false, true
    panel.Visible, panelOpen = false, false
    refreshBtns()
    say("已绑定：" .. label)
end

local function openPanel()
    scan()
    for _, c in ipairs(list:GetChildren()) do
        if c:IsA("GuiObject") then c:Destroy() end
    end
    if #candidates == 0 then
        local t = mkBtn(list, "没扫到按钮 · 点「重新扫描」", 0, 280, 32)
        t.BackgroundTransparency = 0.5
    end
    for i, b in ipairs(candidates) do
        local txt = btnText(b)
        if txt == "" then txt = "(无文字)" end
        if #txt > 18 then txt = string.sub(txt, 1, 18) .. "…" end
        local label = txt .. " · " .. tostring(b.Name)
        local item = mkBtn(list, label, 0, 280, 32)
        item.LayoutOrder = i
        item.MouseButton1Click:Connect(function() bind(b, label) end)
    end
    refreshBtns()
    panel.Visible, panelOpen = true, true
end

local keyLong, keyHold = false, nil
keyBtn.MouseButton1Click:Connect(function()
    if keyLong then keyLong = false; return end
    useKeyOnly = not useKeyOnly
    if not useKeyOnly then scan(); autoPick() end
    refreshBtns()
    say(useKeyOnly and ("改用按键 " .. keyName(CFG["兜底按键"])) or "改回点原脚本按钮")
end)
keyBtn.InputBegan:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then
        keyHold = task.delay(0.4, function()
            keyHold, keyLong = nil, true
            for n, k in ipairs(KEYS) do
                if k == CFG["兜底按键"] then CFG["兜底按键"] = KEYS[n % #KEYS + 1]; break end
            end
            refreshBtns()
            say("键位改为 " .. keyName(CFG["兜底按键"]))
        end)
    end
end)
keyBtn.InputEnded:Connect(function()
    if keyHold then task.cancel(keyHold); keyHold = nil end
end)

modeBtn.MouseButton1Click:Connect(function()
    signalMode = not signalMode
    refreshBtns()
end)
rescanBtn.MouseButton1Click:Connect(function() openPanel(); say("已重新扫描，共找到 " .. #candidates .. " 个按钮") end)
closeBtn.MouseButton1Click:Connect(function() panel.Visible, panelOpen = false, false end)

-- ---------- 6. 拖动 / 短按 / 长按 ----------
local dragging, moved, longPressed = false, false, false
local dragStart, startPos, holdTask

local function isPress(i)
    return i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1
end
local function isMove(i)
    return i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseMovement
end

btn.InputBegan:Connect(function(i)
    if not isPress(i) then return end
    dragging, moved, longPressed = true, false, false
    dragStart = i.Position
    startPos = btn.Position
    holdTask = task.delay(0.45, function()
        holdTask = nil
        if dragging and not moved then
            longPressed, dragging = true, false
            openPanel()
        end
    end)
end)

UIS.InputChanged:Connect(function(i)
    if not dragging or not isMove(i) then return end
    local d = i.Position - dragStart
    if math.abs(d.X) + math.abs(d.Y) > 8 then
        moved = true
        if holdTask then task.cancel(holdTask); holdTask = nil end
    end
    if moved then
        local x, y = clampPos(startPos.X.Offset + d.X, startPos.Y.Offset + d.Y)
        btn.Position = UDim2.fromOffset(x, y)
    end
end)

local function endPress()
    if not dragging then return end
    dragging = false
    if holdTask then task.cancel(holdTask); holdTask = nil end
    if longPressed or moved then return end
    if panelOpen then panel.Visible, panelOpen = false, false; return end
    fire()
end
btn.InputEnded:Connect(endPress)
UIS.InputEnded:Connect(function(i) if isPress(i) then endPress() end end)

-- ---------- 7. 启动 ----------
local deadline = os.clock() + CFG["扫描等待"]
repeat
    scan()
    if #candidates > 0 then break end
    task.wait(0.25)
until os.clock() > deadline
autoPick()

if alive(target) then
    say("快捷键已就绪 · 短按执行，长按设置")
else
    say("没认出执行按钮 · 长按手动指定，或改用按键 " .. keyName(CFG["兜底按键"]))
end
